      'vi': 'Sáu điểm, mười lăm đoạn. Lần lượt tô một đoạn theo màu của mình.\nTạo thành tam giác cùng màu là thua!',
    },
    'ruleSprouts': {
      'en': 'Connect two dots with a straight line; a new dot sprouts in the middle.\nLines can\'t cross. Each dot takes at most 3 lines.\nCan\'t move? You lose.',
      'ko': '점 두 개를 직선으로 잇고, 그 한가운데에 새 점이 생겨요.\n선은 서로 못 넘고, 한 점에 선은 3개까지.\n더 이을 수 없는 사람이 져요.',
      'ja': '2つの点を直線でつなぐと、真ん中に新しい点が生えるよ。\n線は交差できない。1つの点に線は3本まで。\nつなげなくなった人が負け。',
      'zh': '用直线连接两个点，中间会长出一个新点。\n线不能交叉，每个点最多连3条线。\n没法再连的人输。',
      'es': 'Une dos puntos con una recta; en el medio brota un punto nuevo.\nLas líneas no se cruzan. Cada punto admite 3 líneas como máximo.\nSi no puedes mover, pierdes.',
      'pt': 'Ligue dois pontos com uma reta; no meio nasce um ponto novo.\nAs linhas não se cruzam. Cada ponto aceita no máximo 3 linhas.\nQuem não puder jogar, perde.',
      'de': 'Verbinde zwei Punkte mit einer Geraden; in der Mitte spriesst ein neuer Punkt.\nLinien dürfen sich nicht kreuzen. Höchstens 3 Linien pro Punkt.\nWer nicht mehr ziehen kann, verliert.',
      'fr': 'Relie deux points par un trait droit ; un nouveau point pousse au milieu.\nLes traits ne se croisent pas. 3 traits max par point.\nPlus de coup possible ? Tu perds.',
      'id': 'Hubungkan dua titik dengan garis lurus; titik baru tumbuh di tengahnya.\nGaris tidak boleh bersilang. Tiap titik maksimal 3 garis.\nTidak bisa jalan? Kamu kalah.',
      'vi': 'Nối hai điểm bằng một đoạn thẳng; một điểm mới mọc ở giữa.\nCác đoạn không được cắt nhau. Mỗi điểm tối đa 3 đoạn.\nHết nước đi là thua.',
    },
    'ruleHex': {
      'en': 'Take turns filling one cell.\nYou win by linking LEFT to RIGHT. Yerin links TOP to BOTTOM.\nThere are no draws.',
      'ko': '번갈아 한 칸씩 칠해요.\n나는 왼쪽↔오른쪽, 예린은 위↔아래를 이으면 승리!\n무승부는 없어요.',
      'ja': '交互に1マスずつ塗るよ。\n君は左↔右、イェリンは上↔下をつなげば勝ち！\n引き分けはない。',
      'zh': '轮流涂一格。\n你连通左↔右就赢，艺琳连通上↔下。\n没有平局。',
      'es': 'Por turnos, colorea una celda.\nTú ganas uniendo IZQUIERDA y DERECHA. Yerin une ARRIBA y ABAJO.\nNo hay empates.',
      'pt': 'Cada um pinta uma célula por vez.\nVocê vence ligando ESQUERDA e DIREITA. A Yerin liga CIMA e BAIXO.\nNão existe empate.',
