    'nb_w3_1': {
      'en': '1·2·3 is a shape where three rows cancel each other. Leave that.',
      'ko': '1·2·3 은 세 줄이 서로를 지우는 모양. 이걸 남겨.',
      'ja': '1・2・3は三列がお互いを打ち消す形。これを残して。',
      'zh': '1·2·3是三行互相抵消的形状。留下这个。',
      'es': '1·2·3 es una forma donde las tres filas se cancelan entre sí. Deja eso.',
      'pt': '1·2·3 é uma forma em que as três fileiras se cancelam. Deixe assim.',
      'de': '1-2-3 ist eine Form, bei der sich drei Reihen gegenseitig aufheben. Lass genau das übrig.',
      'fr': '1·2·3, c\'est une configuration où trois rangées s\'annulent entre elles. Laisse ça.',
      'id': '1·2·3 adalah bentuk di mana tiga baris saling meniadakan. Sisakan itu.',
      'vi': '1·2·3 là hình mà ba hàng triệt tiêu lẫn nhau. Hãy để lại thế đó.',
    },
    'nb_w3_2': {
      'en': 'In binary, every column has an even number of 1s — that\'s "cancelled".',
      'ko': '이진수로 쓰면 각 자리의 1 개수가 전부 짝수 — 그게 \'지워진\' 상태.',
      'ja': '二進数で書くと、各桁の1の数が全部偶数 — それが「打ち消された」状態。',
      'zh': '用二进制写出来,每一位上1的个数都是偶数——那就是"抵消"的状态。',
      'es': 'En binario, cada columna tiene un número par de unos — eso es estar "cancelado".',
      'pt': 'Em binário, cada coluna tem um número par de uns — isso é estar "cancelado".',
      'de': 'In Binärschreibweise hat jede Spalte eine gerade Anzahl an Einsen — das ist der Zustand „aufgehoben".',
      'fr': 'En binaire, chaque colonne a un nombre pair de 1 — c\'est ça, l\'état « annulé ».',
      'id': 'Kalau ditulis biner, jumlah angka 1 di tiap kolom semuanya genap — itulah keadaan "saling meniadakan".',
      'vi': 'Viết ở dạng nhị phân, mỗi cột có số lượng số 1 là số chẵn — đó chính là trạng thái "triệt tiêu".',
    },
    'nb_w3_3': {
      'en': 'Two equal rows? Empty the third. All different? Calculate.',
      'ko': '두 줄이 같으면 나머지 한 줄을 0으로. 세 줄 다 다르면 계산.',
      'ja': '二列が同じなら残り一列を0に。三列とも違うなら計算。',
      'zh': '两行相同就把第三行清空。三行都不同就得计算。',
      'es': '¿Dos filas iguales? Vacía la tercera. ¿Las tres diferentes? Calcula.',
      'pt': 'Duas fileiras iguais? Esvazie a terceira. As três diferentes? Calcule.',
      'de': 'Zwei Reihen gleich? Leer die dritte. Alle drei verschieden? Rechne.',
      'fr': 'Deux rangées égales ? Vide la troisième. Les trois différentes ? Calcule.',
      'id': 'Dua baris sama? Kosongkan yang ketiga. Ketiganya beda? Hitung.',
      'vi': 'Hai hàng bằng nhau? Dọn sạch hàng thứ ba. Cả ba đều khác nhau? Phải tính toán.',
    },
    'nb_w4_title': {
      'en': 'Grundy\'s game',
      'ko': '그런디의 게임',
      'ja': 'グランディーのゲーム',
