      'ko': '1·2개짜리는 못 쪼개는 \'죽은\' 묶음.',
      'ja': '1・2個の束は分割できない「死んだ」束。',
      'zh': '1、2个的堆是分不开的"死堆"。',
      'es': 'Los montones de 1 o 2 están "muertos" — no se pueden dividir.',
