    },
    'nb_w4_2': {
      'en': '4, 7, 10 and 20 are losing sizes for whoever moves. Hand me those.',
      'ko': '4·7·10·20개는 둘 차례가 지는 크기. 나한테 이걸 넘겨.',
      'ja': '4・7・10・20個は、手番の人が負けるサイズ。これを私に渡して。',
      'zh': '4、7、10、20个是轮到谁走谁就输的数量。把这些留给我。',
      'es': '4, 7, 10 y 20 son tamaños perdedores para quien mueva. Dame esos.',
      'pt': '4, 7, 10 e 20 são tamanhos perdedores para quem for jogar. Me entregue esses.',
      'de': '4, 7, 10 und 20 sind Verlierergrößen für den, der am Zug ist. Gib mir die.',
      'fr': '4, 7, 10 et 20 sont des tailles perdantes pour celui qui joue. Refile-les-moi.',
