      'de': 'Beim Quadrat: iss (2,2), und danach halte die L-Form symmetrisch.',
      'fr': 'Sur un carré, mange (2,2), puis garde la forme en L symétrique.',
      'id': 'Di papan persegi, makan (2,2), lalu jaga bentuk L-nya tetap simetris.',
      'vi': 'Với hình vuông, ăn ô (2,2), sau đó giữ hình chữ L luôn đối xứng.',
    },
    'nb_w8_3': {
      'en': 'On two rows, keep the top exactly one longer than the bottom.',
      'ko': '2줄 판은 위가 아래보다 딱 하나 많게.',
      'ja': '二列の盤面は上が下よりちょうど一つ多く。',
      'zh': '两行的棋盘,让上面比下面正好多一个。',
      'es': 'Con dos filas, mantén la de arriba con exactamente una más que la de abajo.',
      'pt': 'Com duas fileiras, mantenha a de cima com exatamente uma a mais que a de baixo.',
      'de': 'Bei zwei Reihen: die obere genau eins länger als die untere halten.',
      'fr': 'Sur deux rangées, garde le haut exactement un de plus que le bas.',
      'id': 'Di papan dua baris, jaga baris atas selalu tepat satu lebih banyak dari bawah.',
      'vi': 'Với bàn hai hàng, giữ hàng trên nhiều hơn hàng dưới đúng một ô.',
