    'nb_w12_title': {
      'en': 'Building bridges',
      'ko': '다리 놓기',
      'ja': '橋を架ける',
      'zh': '架桥',
      'es': 'Construir puentes',
      'pt': 'Construindo pontes',
      'de': 'Brücken bauen',
      'fr': 'Construire des ponts',
      'id': 'Membangun jembatan',
      'vi': 'Xây cầu',
    },
    'nb_w12_1': {
      'en': 'Center first. Then build bridges that CAN connect, not ones that already do.',
      'ko': '가운데를 먼저. 그리고 \'이어진\' 게 아니라 \'이어질 수 있는\' 다리를 만들어.',
      'ja': 'まず真ん中。それから「つながってる」んじゃなく「つながれる」橋を作って。',
      'zh': '先占中间。然后要建的是"可以连接"的桥,而不是"已经连接"的。',
      'es': 'Primero el centro. Luego construye puentes que PUEDAN conectar, no los que ya lo hacen.',
      'pt': 'Primeiro o centro. Depois construa pontes que PODEM conectar, não as que já conectam.',
      'de': 'Zuerst die Mitte. Dann bau Brücken, die verbunden werden KÖNNEN, nicht solche, die es schon sind.',
      'fr': 'D\'abord le centre. Ensuite, construis des ponts qui PEUVENT se connecter, pas ceux qui le sont déjà.',
      'id': 'Tengah dulu. Lalu bangun jembatan yang BISA tersambung, bukan yang sudah tersambung.',
      'vi': 'Chiếm giữa trước. Rồi xây những cây cầu CÓ THỂ nối lại, chứ không phải đã nối sẵn.',
    },
    'nb_w12_2': {
      'en': 'Place two cells apart: if I block one link, you take the other.',
      'ko': '두 칸 건너 놓기: 상대가 하나를 막으면 다른 하나로 잇는다.',
      'ja': '二マス空けて置く:私が一つを塞いだら、もう一つでつなぐ。',
      'zh': '隔两格放:我堵住一个,你就用另一个连上。',
      'es': 'Coloca a dos casillas de distancia: si bloqueo un enlace, tomas el otro.',
      'pt': 'Coloque a duas casas de distância: se eu bloquear uma ligação, você usa a outra.',
      'de': 'Setz zwei Felder entfernt: Blockiere ich eine Verbindung, nimmst du die andere.',
      'fr': 'Place à deux cases d\'écart : si je bloque un lien, tu prends l\'autre.',
